"""Produce the B06 coverage/depth map without converting scope gaps to passes."""
from pathlib import Path
import hashlib,json,sys
HERE=Path(__file__).parent;ROOT=HERE.parents[3]
sys.path.insert(0,str(HERE))
from author_domains import load
def read(path):return json.loads(path.read_text(encoding='utf-8'))
def write(name,value):(HERE/name).write_text(json.dumps(value,indent=2,ensure_ascii=False)+'\n',encoding='utf-8',newline='\n')
def main():
    rows=[];gaps=[];domains=[];sources={r['id']:r for r in read(ROOT/'research/v5/b06_resources.json')['resources']}
    for number in range(57,65):
        d=load('spec_t'+str(number));did=d['id'];family=d['family'];prefix=d['prefix']
        domains.append(dict(domain=did,status='authored; portable core and selected target evidence separately recorded',previous_state='planned in overhaul_v5; no accepted project/exercise identities existed for this domain',justification=d['purpose'],producer=d['artifact'][0],projects=8,objectives=24,mandatory_target_scope=d['remaining']))
        for n,p in enumerate(d['projects'],1):
            pid=f'PR-{did}-{n:02}';tid=f'{did}.{n:02}';refs=p.get('refs') or d['refs']
            for suffix,artifact,criterion in [('a','D1 prediction, assumptions and invariant',p['reasoning']),('b','D2 source and D3 independent oracle/observations',p['contract']),('c','D4 discriminating counterexample, D5 delayed transfer, D6 evidence limits',p['failure']+' '+p['variant'])]:
                rows.append(dict(objective=tid+'.'+suffix,domain=did,topic=tid,source_topic=[dict(resource_id='R-B06-'+r,inspected_locators=sources['R-B06-'+r]['locators']) for r in refs],teaching=dict(path='curriculum/modules/'+did+'.md',section=tid,status='authored mechanism explanation'),implementation_analysis=dict(project=pid,unit=f'LAB-{prefix}-{n:02}A',artifact=artifact,status='specified; author core executions do not assess learners'),boundary_adversarial=dict(test=family+'.'+p['slug'],mutation=family+'.mutation.'+p['slug'],required_counterexample=p['failure']),independent_assessment=dict(unit=f'LAB-{prefix}-{n:02}B',variant=pid+'-transfer',minimum_days=7,criterion=criterion,status='authored opportunity; no learner or independent reviewer evidence'),assessor='assessor/'+family+'/'+pid+'.md',scope=p['contract'],remaining_required=p.get('external') or d['remaining']))
            gaps.append(dict(id=f'G-B06-{did}-{n:02}-TRANSFER',objective_ids=[tid+'.a',tid+'.b',tid+'.c'],kind='unvalidated independent transfer',severity='required',description=p['variant'],status='authored; not executed or independently assessed',closure='Original learner changed-condition deliverables and objective-specific rubric evidence; retain source and timestamps.'))
        gaps.append(dict(id=f'G-B06-{did}-TARGET',objective_ids=[r['objective'] for r in rows if r['domain']==did],kind='target evidence/implementation depth',severity='required',description=d['remaining'],status='partial author evidence; consult target_validation.json',closure='Complete the named real target experiments, preserving unavailable tools/hardware as gaps and never relabelling hosted models.'))
    for label,text in [('REFERENCES','Complete published C17/C23 texts, exact F439/H745 reference manuals and errata, Arm privileged architecture/page-table passages, selected kernel release compatibility, physical board revision and cryptographic image-verification source scope remain uninspected in B06.'),('COMPILER','Reference compiler implements the precisely stated unsigned expression notation. Local declarations, control-flow, functions and pointers require additional reference implementations, fixtures, semantic rules and executions; target README specifies the milestone sequence.'),('KERNEL','Kernel module and ABI context source supplied, but guest module execution/lockdep/RCU paths and actual RV/AArch64 reset/trap/translation implementations remain required. Cross-assembly is narrower evidence.'),('PERFORMANCE','No resource/performance campaign has been measured. Required timing, latency, stack/code-size and memory-traffic comparisons must use equivalent contracts and retained tool/machine configuration.'),('PHYSICAL','No physical board run or interface capture exists for this batch. Dedicated F439/H745 update/reset, peer-core, flash and interface measurements require separately authorized physical execution.')]:
        gaps.append(dict(id='G-B06-'+label,kind='source/implementation/experiment gap',severity='required',description=text,status='open',closure='Supply bounded inspected references or source-bound observed implementation/target evidence; finite tests do not prove absolute mastery.'))
    pins={p.relative_to(ROOT).as_posix():hashlib.sha256(p.read_bytes()).hexdigest() for p in [HERE/'author_domains.py',HERE/'author_targets.py',HERE/'register_sources.py',*sorted(HERE.glob('spec_t*.py')),ROOT/'research/v5/b06_resources.json',ROOT/'research/v5/b06_taxonomy.json']}
    write('coverage.json',dict(batch='B06',domains=domains,objective_map=rows,completion_claim='Authored domain integration and bounded experiments only; remaining required gaps prevent comprehensive completion.',input_sha256=pins))
    write('gap_ledger.json',dict(batch='B06',gaps=gaps,policy='Required scope remains required at batch boundaries; independent assessment and physical claims cannot be inferred from author execution.'))
    write('remaining_work.json',dict(batch='B06',authored_domains=[d['domain'] for d in domains],required_open=[g['id'] for g in gaps],comprehensive_complete=False,next_dependency_order=['Complete unavailable primary target reference inspection','Extend target implementations from declared portable contracts','Execute guest/solver/changed-condition campaigns','Collect separately authorized physical evidence','Conduct delayed learner and independent assessment']))
    print(json.dumps({'domains':len(domains),'objectives':len(rows),'required_open':len(gaps)}))
if __name__=='__main__':main()
